SELECT un_production.id, un_production.product_id, un_production.quantity, un_production.create_time, part.serial_number, part.specification, task.ask_complete_time, task.task_type_enum, task.id task_id, part.material, project.id 'project.id', project.`name` 'project.`name`', project.short_name 'project.short_name', project.serial_number 'project.serial_number', monomer.id 'monomer.id', monomer.`name` 'monomer.name', area.id 'area.id', area.`name` 'area.name', workshop.id 'workshop.id', workshop.`name` 'workshop.name', production_line.id 'production_line.id', production_line.`name` 'production_line.name', gro.id 'groups.id', gro.`name` 'groups.name' , user.id 'user.id', user.`name` 'user.name' FROM mes_building_task_need_machine_part_scheduling_un_production un_production LEFT JOIN tech_machine_part part ON un_production.product_id = part.id LEFT JOIN contract_project project ON un_production.project_id = project.id LEFT JOIN plan_monomer monomer ON un_production.monomer_id = monomer.id LEFT JOIN mes_building_task task ON un_production.task_id = task.id LEFT JOIN tech_artifact artifact ON artifact.id = task.product_id LEFT JOIN plan_area area ON un_production.area_id = area.id LEFT JOIN mes_building_workshop workshop ON un_production.workshop_id = workshop.id LEFT JOIN mes_building_production_line production_line ON un_production.production_line_id = production_line.id LEFT JOIN mes_building_groups gro ON un_production.groups_id = gro.id LEFT JOIN sys_user user ON user.id=un_production.use_id
un_production.bool_delete_enum=0
AND un_production.project_id=#{projectId}
AND un_production.monomer_id=#{monomerId}
AND un_production.area_id=#{areaId}
AND un_production.workshop_id=#{workshopId}
AND un_production.production_line_id=#{productionLineId}
AND un_production.groups_id=#{groupsId}
AND part.serial_number LIKE concat('%',#{serialNumber},'%')
AND artifact.serial_number LIKE concat('%',#{artifactSerialNumber},'%')
